int main() {
    int a[2][3] = {{1, 2, 3}, {4, 5, 6}};
    int b[2][3] = {{6, 5, 4}, {3, 2, 1}};
    int sum[2][3];

    for (int r = 0; r < 2; r++) {
        for (int c = 0; c < 3; c++) {
            sum[r][c] = a[r][c] + b[r][c];
            printf("%d ", sum[r][c]);
        }
        printf("\n");
    }
    return 0;
}

